referenceSolution:
function selectTodoView(todos, filter) {
  const visible = todos
    .filter((t) => (filter === 'active' ? !t.done : filter === 'done' ? t.done : true))
    .map((t) => t.text);
  const remaining = todos.filter((t) => !t.done).length;
  return { visible, remaining };
}

