function depsChanged(prevDeps, nextDeps) {
  if (prevDeps === null) return true;
  if (prevDeps.length !== nextDeps.length) return true;
  for (let i = 0; i < nextDeps.length; i++) {
    if (!Object.is(prevDeps[i], nextDeps[i])) return true;
  }
  return false;
}

